// Capture one Home Assistant snapshot and acquire the runtime evaluation lock.
// Do not start a control calculation until the persistent current-day journal has
// been read (or an empty current-day journal has been initialized). This prevents
// a deploy/reinstall startup cycle from creating a fresh zero-sample accuracy object
// and publishing it over the saved Daily Control Accuracy before restore completes.
if (global.get('homePvControlPersistentHistoryReady') !== true) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'waiting for daily history' });
    return null;
}

const now = Date.now();
const lockKey = 'homePvControlRuntimeEvaluationLock';
const lockTimeoutMs = 12000;
const existingLock = global.get(lockKey);
const lockIsFresh = existingLock && existingLock.active === true &&
    Number.isFinite(Number(existingLock.startedAt)) &&
    (now - Number(existingLock.startedAt)) < lockTimeoutMs;

if (lockIsFresh) {
    global.set('homePvControlDroppedRuntimeTriggers',
        Number(global.get('homePvControlDroppedRuntimeTriggers') || 0) + 1);
    node.status({ fill: 'yellow', shape: 'ring', text: 'evaluation already active' });
    return null;
}

const cycleId = Number(global.get('homePvControlRuntimeCycleCounter') || 0) + 1;
global.set('homePvControlRuntimeCycleCounter', cycleId);
global.set('homePvControlLatestRuntimeCycleId', cycleId);
global.set(lockKey, { active: true, cycleId, startedAt: now });
// Publish the cycle identity onto the message immediately. Scoped Catch handlers
// use it to release only this failed cycle's lock, never a newer evaluation.
msg.hpvc = Object.assign(msg.hpvc || {}, { now, cycleId });

const liveHaStates = global.get('homeassistant.homeAssistant.states') || {};
// Deep-clone the state map so every stage sees one immutable cycle snapshot.
const haStates = JSON.parse(JSON.stringify(liveHaStates));
function getState(entity, fallback = undefined) {
    if (!entity || !haStates[entity]) return fallback;
    return haStates[entity].state;
}
function numericState(entity, fallback = 0) {
    const value = Number(getState(entity, fallback));
    return Number.isFinite(value) ? value : fallback;
}
function numericInputValid(entity) {
    if (!validEntityId(entity) || !haStates[entity]) return false;
    const raw = String(haStates[entity].state ?? '').trim().toLowerCase();
    if (['', 'unknown', 'unavailable', 'none'].includes(raw)) return false;
    return Number.isFinite(Number(raw));
}
function stateUpdatedMs(entity) {
    if (!validEntityId(entity) || !haStates[entity]) return null;
    const raw = haStates[entity].last_updated || haStates[entity].last_changed || '';
    const parsed = Date.parse(raw);
    return Number.isFinite(parsed) ? parsed : null;
}
function stringState(entity, fallback = '') {
    const value = getState(entity, fallback);
    return value === undefined || value === null ? fallback : String(value);
}
function validEntityId(entity) {
    return typeof entity === 'string' && /^[a-z0-9_]+\.[a-z0-9_]+$/.test(entity.trim().toLowerCase());
}
function entityAvailable(entity) {
    if (!validEntityId(entity) || !haStates[entity]) return false;
    const state = String(haStates[entity].state ?? '').trim().toLowerCase();
    return !['unknown', 'unavailable', 'none', ''].includes(state);
}
function configuredEntity(helperEntity) {
    const entity = stringState(helperEntity, '').trim();
    return validEntityId(entity) && entity !== 'select_entity_first' ? entity : '';
}
function hbcBatteryPowerEntity(index) {
    return `sensor.marstek_m${index}_ac_power`;
}
function hbcBatterySocEntity(index) {
    return `sensor.marstek_m${index}_battery_state_of_charge`;
}

const enabled = stringState('input_boolean.hpvc_enabled', 'on') === 'on';
const notify = stringState('input_boolean.hpvc_notifications', 'on') === 'on';
const hbcControlRequested = stringState('input_boolean.hpvc_control_hbc_strategy', 'off') === 'on';
const negativePriceHbcCharge = stringState('input_boolean.hpvc_negative_price_hbc_charge', 'off') === 'on';
const defaultsRestoredEventState = stringState('input_button.hpvc_defaults_restored_event', '');

const gridEntity = configuredEntity('input_text.hpvc_grid_power_sensor');
const marketEntity = configuredEntity('input_text.hpvc_market_price_sensor');
const allInEntity = configuredEntity('input_text.hpvc_all_in_price_sensor');
const pvPowerEntity = configuredEntity('input_text.hpvc_pv_power_sensor');
const hbcStrategyEntity = 'input_select.house_battery_strategy';
const hasHbc = entityAvailable(hbcStrategyEntity);

const market = numericState(marketEntity, 999);
const allIn = numericState(allInEntity, 999);
const grid = numericState(gridEntity, 0);
const pvPower = numericState(pvPowerEntity, 0);
const pvPowerUpdatedMs = stateUpdatedMs(pvPowerEntity);
// Keep validity separate from the numeric fallback. A missing/unavailable PV sensor
// may still carry 0 in pvPower for display compatibility, but that fallback must
// never be treated as measured 0 W by Night Restore or normal control decisions.
const pvPowerValid = numericInputValid(pvPowerEntity);

msg.hpvc = Object.assign(msg.hpvc || {}, {
    now,
    cycleId,
    haStates,
    enabled,
    notify,
    hbcControlRequested,
    negativePriceHbcCharge,
    defaultsRestoredEventState,
    gridEntity,
    marketEntity,
    allInEntity,
    pvPowerEntity,
    hbcStrategyEntity,
    hasHbc,
    market,
    allIn,
    grid,
    pvPower,
    pvPowerValid,
    pvPowerUpdatedMs,
    newInsights: [],
    hbcBatteryPowerEntity,
    hbcBatterySocEntity
});
node.status({ fill: 'blue', shape: 'dot', text: `cycle ${cycleId}` });
return msg;

// Read all control settings from the cycle's immutable Home Assistant snapshot.
const hpvc = msg.hpvc || {};
const haStates = hpvc.haStates || {};
function state(entity, fallback = undefined) {
    return entity && haStates[entity] && haStates[entity].state !== undefined
        ? haStates[entity].state
        : fallback;
}
function number(entity, fallback = 0) {
    const value = Number(state(entity, fallback));
    return Number.isFinite(value) ? value : fallback;
}
function numericStateValid(entity) {
    const raw = state(entity, undefined);
    if (raw === undefined || raw === null) return false;
    const text = String(raw).trim().toLowerCase();
    return !['', 'unknown', 'unavailable', 'none'].includes(text) && Number.isFinite(Number(raw));
}

const settingEntities = [
    'input_number.hpvc_pv_limiting_price',
    'input_number.hpvc_battery_price_hysteresis',
    'input_number.hpvc_export_start_threshold',
    'input_number.hpvc_export_stop_threshold',
    'input_number.hpvc_import_restore_threshold',
    'input_number.hpvc_pv_min_power_for_control',
    'input_number.hpvc_pv_night_restore_power',
    'input_number.hpvc_cooldown_seconds',
    'input_number.hpvc_pv_adjust_deadband'
];
const invalidSettingEntities = settingEntities.filter(entity => !numericStateValid(entity));
const settingsAvailabilityValid = invalidSettingEntities.length === 0;

const limitingPrice = number('input_number.hpvc_pv_limiting_price', 0);
const hysteresis = number('input_number.hpvc_battery_price_hysteresis', 0.02);
const pvRestorePrice = limitingPrice + Math.max(0, hysteresis);
const exportStart = number('input_number.hpvc_export_start_threshold', -150);
const exportTarget = number('input_number.hpvc_export_stop_threshold', 0);
const importRecalc = number('input_number.hpvc_import_restore_threshold', 150);
const minPvPower = number('input_number.hpvc_pv_min_power_for_control', 100);
const nightRestorePower = number('input_number.hpvc_pv_night_restore_power', 10);
const cooldownSeconds = number('input_number.hpvc_cooldown_seconds', 30);
const deadband = number('input_number.hpvc_pv_adjust_deadband', 25);

const thresholdConfigurationValid =
    settingsAvailabilityValid &&
    Number.isFinite(limitingPrice) && limitingPrice >= -0.50 && limitingPrice <= 0.20 &&
    Number.isFinite(hysteresis) && hysteresis >= 0 && hysteresis <= 0.10 &&
    exportStart >= -5000 && exportStart <= 0 &&
    exportTarget >= -5000 && exportTarget <= 500 &&
    importRecalc >= 0 && importRecalc <= 5000 &&
    exportStart < exportTarget &&
    exportTarget < importRecalc &&
    minPvPower >= 0 && minPvPower <= 5000 &&
    nightRestorePower >= 0 && nightRestorePower <= 1000 &&
    cooldownSeconds >= 10 && cooldownSeconds <= 60 &&
    deadband >= 1 && deadband <= 500;

const thresholdConfigurationError = thresholdConfigurationValid
    ? ''
    : (invalidSettingEntities.length > 0
        ? `Invalid or unavailable setting helpers: ${invalidSettingEntities.join(', ')}`
        : `Invalid settings: values must remain inside their declared v1.4.0 helper ranges and require Export Start < Target Export < Import Restore (current thresholds: ${exportStart} W, ${exportTarget} W, ${importRecalc} W)`);

Object.assign(hpvc, {
    limitingPrice,
    hysteresis,
    pvRestorePrice,
    exportStart,
    exportTarget,
    importRecalc,
    thresholdConfigurationValid,
    thresholdConfigurationError,
    minPvPower,
    nightRestorePower,
    cooldownSeconds,
    deadband,
});
msg.hpvc = hpvc;
return msg;

// Read Sun and Night Restore Inputs

// Read HPVC Inputs
// Staged HPVC v1.4.0 control function. Core PV limiting, restore and cooldown remain staged; negative all-in handling uses PV-minimum protection with an optional confirmed HBC force-charge override. HBC integration
// follows the documented v1.4.0 Charge Priority architecture.

// Take one Home Assistant state snapshot for the whole evaluation. Every
// downstream node receives this same snapshot in msg.hpvc, so concurrent
// evaluations cannot overwrite each other's state picture.
const haStates = (msg.hpvc && msg.hpvc.haStates) || {};

function states() {
    return haStates;
}

function getState(entity, fallback = undefined) {
    const s = states();
    if (!entity || !s[entity]) return fallback;
    return s[entity].state;
}

function numEntity(entity, fallback = 0) {
    const raw = getState(entity, fallback);
    const text = raw === undefined || raw === null ? '' : String(raw).trim();
    if (!text || ['unknown', 'unavailable', 'none'].includes(text.toLowerCase())) return fallback;
    const v = Number(text);
    return Number.isFinite(v) ? v : fallback;
}

function strEntity(entity, fallback = '') {
    const v = getState(entity, fallback);
    return v === undefined || v === null ? fallback : String(v);
}

// Settings helper wrappers. Kept separate from numEntity()/strEntity() for readability
// and future helper-specific validation.

function validEntity(entity) {
    return typeof entity === 'string' && entity.includes('.');
}

function entityExists(entity) {
    if (!validEntity(entity)) return false;
    const s = states();
    if (!s[entity]) return false;
    const st = String(s[entity].state || '').trim().toLowerCase();
    return !['unknown', 'unavailable', 'none', ''].includes(st);
}

let { hbcBatteryPowerEntity, hbcBatterySocEntity, now, hbcControlRequested, marketEntity, allInEntity, hbcStrategyEntity, hasHbc, pvPower, pvPowerValid, nightRestorePower } = msg.hpvc;

const nightRestorePersistenceMs = 120000;
const nightRestoreRecoveryPersistenceMs = 30000;
const nightRestoreEntryThreshold = Number(nightRestorePower);
// Keep at least 15 W of hysteresis above the configured entry threshold. With the
// default 10 W Night Restore threshold this produces the intended 25 W recovery point.
const nightRestoreRecoveryPower = Math.max(25, nightRestoreEntryThreshold + 15);
const sunEntity = 'sun.sun';
const sunAvailable = entityExists(sunEntity);
const sunState = strEntity(sunEntity, 'unavailable').trim().toLowerCase();
const sunBelowHorizon = sunAvailable && sunState === 'below_horizon';
// Only a genuinely valid numeric PV state can start or end Night Restore.
// Read HPVC Core Configuration intentionally keeps a numeric fallback for display
// compatibility; pvPowerValid=false prevents an unavailable/unknown sensor from being
// mistaken for a real 0 W measurement.
const pvPowerNumeric = pvPowerValid !== false && Number.isFinite(Number(pvPower));
const lowPvNightCandidate = pvPowerNumeric && Number(pvPower) <= nightRestoreEntryThreshold;
const nightRestoreRecoveryCandidate = pvPowerNumeric && Number(pvPower) > nightRestoreRecoveryPower;

// Actual PV remains authoritative so a wrongly configured Home Assistant location
// cannot strand HPVC in Night Restore. Entry requires 120 s of sustained low PV.
// Recovery deliberately uses a higher threshold and 30 s persistence so dawn noise
// or a single small OpenDTU sample cannot flap Night Restore on/off.
const nightRestoreCondition = lowPvNightCandidate;
let nightRestoreActive = flow.get('homePvControlNightRestoreActive') === true;
const nightRestoreSinceStored = Number(flow.get('homePvControlNightRestoreSince'));
let nightRestoreSince = Number.isFinite(nightRestoreSinceStored) ? nightRestoreSinceStored : 0;
const nightRestoreRecoverySinceStored = Number(flow.get('homePvControlNightRestoreRecoverySince'));
let nightRestoreRecoverySince = Number.isFinite(nightRestoreRecoverySinceStored) ? nightRestoreRecoverySinceStored : 0;

if (nightRestoreActive) {
    // Stay in Night Restore until PV is clearly back for 30 continuous seconds.
    if (nightRestoreRecoveryCandidate) {
        if (!nightRestoreRecoverySince) nightRestoreRecoverySince = now;
        if ((now - nightRestoreRecoverySince) >= nightRestoreRecoveryPersistenceMs) {
            nightRestoreActive = false;
            nightRestoreSince = 0;
            nightRestoreRecoverySince = 0;
        }
    } else {
        nightRestoreRecoverySince = 0;
    }
} else {
    nightRestoreRecoverySince = 0;
    if (nightRestoreCondition) {
        if (!nightRestoreSince) nightRestoreSince = now;
        if ((now - nightRestoreSince) >= nightRestorePersistenceMs) {
            nightRestoreActive = true;
        }
    } else if (!pvPowerNumeric && nightRestoreSince > 0) {
        // If PV telemetry disappears after a valid low-PV sample already started
        // the night timer, preserve that pending transition instead of instantly
        // dropping back into the daytime safety path.
        // Only sun.sun below_horizon may corroborate completion while PV is absent.
        // Without that corroboration, an unavailable PV value is never promoted to
        // Night Restore: the pending window expires after the original 120 seconds.
        if ((now - nightRestoreSince) >= nightRestorePersistenceMs) {
            if (sunBelowHorizon) {
                nightRestoreActive = true;
            } else {
                nightRestoreSince = 0;
            }
        }
    } else {
        nightRestoreSince = 0;
    }
}

flow.set('homePvControlNightRestoreSince', nightRestoreSince);
flow.set('homePvControlNightRestoreRecoverySince', nightRestoreRecoverySince);
flow.set('homePvControlNightRestoreActive', nightRestoreActive);

const nightRestorePending = !nightRestoreActive && nightRestoreSince > 0;
const usablePvReturned = !nightRestoreActive && pvPowerNumeric && Number(pvPower) > nightRestoreRecoveryPower;
const nightRestoreSource = nightRestoreActive
    ? (sunBelowHorizon ? 'sun.sun below horizon + low PV' : 'low-PV fallback')
    : (nightRestoreRecoveryCandidate
        ? (nightRestoreRecoverySince ? 'PV recovery pending' : 'usable PV returned')
        : (lowPvNightCandidate ? (sunBelowHorizon ? 'sun.sun below horizon + low PV' : 'low-PV fallback') : 'PV unavailable'));
// Clear the former context key from pre-v1.3.0 development builds so stale data cannot influence diagnostics.

msg.hpvc = Object.assign(msg.hpvc || {}, { now, hbcControlRequested, marketEntity, allInEntity, hbcStrategyEntity, hasHbc, pvPower, pvPowerValid, nightRestorePower, sunAvailable, sunState, sunBelowHorizon, lowPvNightCandidate, usablePvReturned, nightRestoreCondition, nightRestoreSource, hbcBatteryPowerEntity, hbcBatterySocEntity, nightRestorePersistenceMs, nightRestoreRecoveryPersistenceMs, nightRestoreRecoveryPower, nightRestoreRecoveryCandidate, nightRestoreRecoverySince, nightRestoreActive, nightRestorePending, nightRestoreSince });
return msg;

// Read HBC availability and validate per-battery telemetry freshness.
const haStates = (msg.hpvc && msg.hpvc.haStates) || {};

function stateObject(entity) {
    return entity && haStates[entity] ? haStates[entity] : null;
}
function stateText(entity, fallback = '') {
    const item = stateObject(entity);
    return item && item.state !== undefined ? String(item.state) : fallback;
}
function numericState(entity) {
    const raw = stateText(entity, '').trim().toLowerCase();
    if (['', 'unknown', 'unavailable', 'none'].includes(raw)) return null;
    const value = Number(raw);
    return Number.isFinite(value) ? value : null;
}
function validEntity(entity) {
    return typeof entity === 'string' && entity.includes('.');
}
function entityAvailable(entity) {
    if (!validEntity(entity)) return false;
    const raw = stateText(entity, '').trim().toLowerCase();
    return !['', 'unknown', 'unavailable', 'none'].includes(raw);
}
function stateUpdatedMs(entity) {
    const item = stateObject(entity);
    if (!item) return null;
    const timestamp = Date.parse(item.last_updated || item.last_changed || '');
    return Number.isFinite(timestamp) ? timestamp : null;
}
function stateAgeMs(entity, now) {
    const timestamp = stateUpdatedMs(entity);
    return Number.isFinite(timestamp) ? Math.max(0, now - timestamp) : null;
}
function attributeHeartbeatMs(entity) {
    const item = stateObject(entity);
    const attrs = item && item.attributes && typeof item.attributes === 'object' ? item.attributes : {};
    const preferredKeys = [
        'last_seen', 'lastSeen', 'last_update', 'lastUpdate', 'updated_at', 'updatedAt',
        'timestamp', 'device_timestamp', 'deviceTimestamp', 'heartbeat', 'last_communication',
        'lastCommunication', 'last_received', 'lastReceived'
    ];
    let newest = null;
    for (const key of preferredKeys) {
        if (!(key in attrs)) continue;
        const raw = attrs[key];
        let parsed = null;
        if (typeof raw === 'number' && Number.isFinite(raw)) {
            parsed = raw > 1e12 ? raw : raw > 1e9 ? raw * 1000 : null;
        } else if (typeof raw === 'string' && raw.trim()) {
            const numeric = Number(raw);
            if (Number.isFinite(numeric) && numeric > 1e9) parsed = numeric > 1e12 ? numeric : numeric * 1000;
            else {
                const date = Date.parse(raw);
                if (Number.isFinite(date)) parsed = date;
            }
        }
        if (Number.isFinite(parsed)) newest = newest === null ? parsed : Math.max(newest, parsed);
    }
    return newest;
}
function ageText(ageMs) {
    return Number.isFinite(ageMs) ? `${Math.round(ageMs / 1000)}s` : 'unknown age';
}

const hpvc = msg.hpvc || {};
const now = Number(hpvc.now) || Date.now();
const hbcControlRequested = hpvc.hbcControlRequested === true;
const hbcStrategyEntity = hpvc.hbcStrategyEntity || 'input_select.house_battery_strategy';
const hasHbc = entityAvailable(hbcStrategyEntity);
const currentStrategy = stateText(hbcStrategyEntity, 'unknown');
const strategyState = stateObject(hbcStrategyEntity);
const hbcStrategyOptions = Array.isArray(strategyState?.attributes?.options)
    ? strategyState.attributes.options.map(String)
    : [];
const hbcActiveSubStrategyEntity = 'input_text.house_battery_strategy_active_sub_strategy';
const activeSubStrategy = stateText(hbcActiveSubStrategyEntity, 'unknown');
const activeSubStrategyNormalized = activeSubStrategy.trim().toLowerCase();
const hbcStrategyControlAvailable = hasHbc && hbcStrategyOptions.length > 0;
const hbcExecutionStateAvailable = entityAvailable(hbcActiveSubStrategyEntity);

// Power must update frequently because its sign determines whether Charge Priority
// is active. SOC changes more slowly, so it intentionally has a longer limit.
const batteryPowerFreshnessMs = 120000;       // 2 minutes while charging/discharging
const batteryIdlePowerFreshnessMs = 300000;   // 5 minutes while near-zero/idle
const batterySocFreshnessMs = 7200000;        // 2 hours: integer SOC can legitimately remain unchanged while idle or tapering
const batterySteadyActiveMaxTrustMs = 7200000; // 2 hours without a device heartbeat while valid power/SOC still corroborate each other
const batteryIdleDeadband = Math.max(1, Number(hpvc.deadband || 25));
const hbcBatteryCountEntity = 'input_number.house_battery_count';
const hbcBatteryCountAvailable = entityAvailable(hbcBatteryCountEntity);
const countRaw = numericState(hbcBatteryCountEntity);
// HBC 4.15.0 supports 1–6 batteries. Keep the historical one-battery
// compatibility fallback only when the helper is genuinely unavailable/missing;
// a present but non-numeric/out-of-contract value is a configuration fault.
const hbcBatteryCountConfigurationValid = !hbcBatteryCountAvailable ||
    (countRaw !== null && Number.isInteger(countRaw) && countRaw >= 0 && countRaw <= 6);
const hbcBatteryCountConfigurationReason = hbcBatteryCountConfigurationValid
    ? ''
    : `HBC battery count ${countRaw === null ? stateText(hbcBatteryCountEntity, 'invalid') : countRaw} is invalid; HBC 4.15.0 requires a whole number from 0 to 6.`;
const hbcSafetyBatteryCount = hbcControlRequested
    ? (!hbcBatteryCountAvailable ? 1 : (hbcBatteryCountConfigurationValid ? countRaw : 0))
    : 0;
const telemetryHealth = [];
const hbcBatterySensorFaults = [];
const hbcBatteryControlExclusions = [];
let hbcUsableBatteryCount = 0;

// Cutoff helpers are configuration, not telemetry defaults. Remember the last
// complete valid pair so a brief HA helper outage does not change battery
// semantics to an invented 100%/0%. If no valid pair has ever been observed,
// that battery is excluded from HBC Charge Priority until configuration returns.
let cutoffMemory = global.get('homePvControlBatteryCutoffMemory') || flow.get('homePvControlBatteryCutoffMemory');
if (!cutoffMemory || typeof cutoffMemory !== 'object') cutoffMemory = { batteries: {} };
if (!cutoffMemory.batteries || typeof cutoffMemory.batteries !== 'object') cutoffMemory.batteries = {};

for (let i = 1; i <= hbcSafetyBatteryCount; i++) {
    const powerEntity = `sensor.marstek_m${i}_ac_power`;
    const socEntity = `sensor.marstek_m${i}_battery_state_of_charge`;
    const chargingCutoffEntity = `input_number.marstek_m${i}_charging_cutoff_capacity`;
    const dischargingCutoffEntity = `input_number.marstek_m${i}_discharging_cutoff_capacity`;
    const rs485Entity = `select.marstek_m${i}_rs485_control_mode`;
    const rs485State = stateText(rs485Entity, '').trim().toLowerCase();
    const rs485Available = entityAvailable(rs485Entity);
    const rs485Enabled = rs485State === 'enable';
    const power = numericState(powerEntity);
    const soc = numericState(socEntity);
    const chargingCutoffRaw = numericState(chargingCutoffEntity);
    const dischargingCutoffRaw = numericState(dischargingCutoffEntity);
    const chargingCutoffAvailable = entityAvailable(chargingCutoffEntity);
    const dischargingCutoffAvailable = entityAvailable(dischargingCutoffEntity);
    const liveCutoffHelpersComplete = chargingCutoffAvailable && dischargingCutoffAvailable;
    const liveCutoffHelpersMissing = !chargingCutoffAvailable || !dischargingCutoffAvailable;
    const liveChargingCutoffValid = chargingCutoffRaw !== null && chargingCutoffRaw >= 0 && chargingCutoffRaw <= 100;
    const liveDischargingCutoffValid = dischargingCutoffRaw !== null && dischargingCutoffRaw >= 0 && dischargingCutoffRaw <= 100;
    const liveCutoffPairValid = liveCutoffHelpersComplete && liveChargingCutoffValid && liveDischargingCutoffValid &&
        dischargingCutoffRaw < chargingCutoffRaw;
    const liveCutoffPairInvalid = liveCutoffHelpersComplete && !liveCutoffPairValid;
    if (liveCutoffPairValid) {
        cutoffMemory.batteries[i] = {
            charging: Number(chargingCutoffRaw),
            discharging: Number(dischargingCutoffRaw),
            updated: now
        };
    }
    const rememberedCutoff = cutoffMemory.batteries[i];
    const rememberedCutoffValid = !!rememberedCutoff &&
        Number.isFinite(Number(rememberedCutoff.charging)) &&
        Number.isFinite(Number(rememberedCutoff.discharging)) &&
        Number(rememberedCutoff.charging) >= 0 && Number(rememberedCutoff.charging) <= 100 &&
        Number(rememberedCutoff.discharging) >= 0 && Number(rememberedCutoff.discharging) <= 100 &&
        Number(rememberedCutoff.discharging) < Number(rememberedCutoff.charging);
    // Remembered values bridge a genuinely unavailable helper only. A live helper that is
    // present but invalid is a configuration fault and must never be hidden by old memory.
    const useRememberedCutoff = liveCutoffHelpersMissing && rememberedCutoffValid;
    const cutoffConfigUsable = liveCutoffPairValid || useRememberedCutoff;
    const chargingCutoff = liveCutoffPairValid
        ? Number(chargingCutoffRaw)
        : useRememberedCutoff ? Number(rememberedCutoff.charging) : null;
    const dischargingCutoff = liveCutoffPairValid
        ? Number(dischargingCutoffRaw)
        : useRememberedCutoff ? Number(rememberedCutoff.discharging) : null;
    const cutoffSource = liveCutoffPairValid ? 'live' : useRememberedCutoff ? 'remembered' : 'unknown';
    const cutoffConfigIssue = liveCutoffPairValid || useRememberedCutoff
        ? ''
        : liveCutoffPairInvalid
            ? (!liveChargingCutoffValid || !liveDischargingCutoffValid
                ? 'live charging/discharging cutoff is non-numeric or outside 0-100%'
                : 'live discharging cutoff must be lower than charging cutoff')
            : 'charging/discharging cutoff unavailable and no valid remembered pair exists';
    const powerUpdatedMs = stateUpdatedMs(powerEntity);
    const socUpdatedMs = stateUpdatedMs(socEntity);
    const powerAgeMs = stateAgeMs(powerEntity, now);
    const socAgeMs = stateAgeMs(socEntity, now);
    const powerHeartbeatMs = attributeHeartbeatMs(powerEntity);
    const socHeartbeatMs = attributeHeartbeatMs(socEntity);
    const heartbeatMs = [powerHeartbeatMs, socHeartbeatMs].filter(Number.isFinite).reduce(
        (latest, value) => latest === null ? value : Math.max(latest, value), null
    );
    const heartbeatAgeMs = Number.isFinite(heartbeatMs) ? Math.max(0, now - heartbeatMs) : null;
    const heartbeatFresh = Number.isFinite(heartbeatAgeMs) && heartbeatAgeMs <= batteryPowerFreshnessMs;
    const powerNumeric = power !== null;
    const socNumeric = soc !== null && soc >= 0 && soc <= 100;
    const activePower = powerNumeric && Math.abs(power) >= batteryIdleDeadband;
    const atChargingCutoff = socNumeric && cutoffConfigUsable && soc >= chargingCutoff;
    const atDischargingCutoff = socNumeric && cutoffConfigUsable && soc <= dischargingCutoff;
    const boundaryIdle = powerNumeric && !activePower && (atChargingCutoff || atDischargingCutoff);
    // Marstek commonly leaves an unchanged 0 W idle value untouched for more than
