        authority = { direction, remainingAbs: 0, ts: now };
    }
    authority.remainingAbs = Math.max(0, Number(authority.remainingAbs || 0)) + magnitude;
    authority.ts = now;
    global.set(key, authority);
}

function claimExternalPvResponseAuthority(pvDelta, kind) {
    const authority = getExternalPvResponseAuthority(kind);
    const pv = Number(pvDelta);
    if (!authority || !Number.isFinite(pv) || Math.abs(pv) < PHYSICAL_COMPONENT_NOISE_W ||
        Math.sign(pv) !== Math.sign(Number(authority.direction || 0))) return 0;
    const claimAbs = Math.min(Math.abs(pv), Number(authority.remainingAbs || 0));
    if (claimAbs < PHYSICAL_COMPONENT_NOISE_W) return 0;
    authority.remainingAbs = Math.max(0, Number(authority.remainingAbs || 0) - claimAbs);
    global.set(externalAuthorityKey(kind), authority.remainingAbs >= PHYSICAL_COMPONENT_NOISE_W ? authority : null);
    return Math.sign(pv) * claimAbs;
}

function pushAttributionDiagnostic(entry) {
    const diagnostic = { ts: now, ...entry };
    let history = Array.isArray(global.get('homePvControlAttributionDiagnosticHistory'))
        ? global.get('homePvControlAttributionDiagnosticHistory') : [];
    history.push(diagnostic);
    history = history.slice(-ATTRIBUTION_DIAGNOSTIC_MAX_EVENTS);
    global.set('homePvControlAttributionDiagnosticHistory', history);
}

const detectorCoreInputsValid =
    enabled &&
    thresholdConfigurationValid &&
    stateIsNumeric(gridEntity) &&
    stateIsNumeric(pvPowerEntity) &&
    completeInverterGroup;
let detectorContinuityGeneration = Number(global.get('homePvControlPhysicalDetectorGeneration') || 1);
// Attribution transients have their own day/revision identity. Do not infer rollover
// from the persisted Daily Accuracy object: the independent journal/midnight flow may
// reset that object before this runtime chain executes. This guard therefore prevents
// both cross-midnight leakage and reuse of transient events/authorities from an older
// attribution revision after a deploy.
const attributionContextKey = global.get('homePvControlAttributionContext') || null;
const attributionContextMismatch = !attributionContextKey ||
    String(attributionContextKey.date || '') !== String(accuracyDateKey) ||
    Number(attributionContextKey.revision) !== Number(headlineAttributionRevision);
if (attributionContextMismatch) {
    global.set('homePvControlPhysicalDetectorSample', null);
    global.set('homePvControlPendingPhysicalEvent', null);
    global.set('homePvControlPvCommandHistory', []);
    global.set('homePvControlRecentPhysicalEvents', []);
    global.set('homePvControlLastExternalLimitChange', null);
    global.set('homePvControlPvResponseAuthority', null);
    global.set('homePvControlPvResponseAuthorityRaw', null);
    global.set('homePvControlExternalPvResponseAuthority', null);
    global.set('homePvControlExternalPvResponseAuthorityRaw', null);
    global.set('homePvControlAttributionDiagnosticHistory', []);
    detectorContinuityGeneration += 1;
    global.set('homePvControlPhysicalDetectorGeneration', detectorContinuityGeneration);
}
global.set('homePvControlAttributionContext', {
    date: accuracyDateKey,
    revision: headlineAttributionRevision
});
let physicalEvents = Array.isArray(global.get('homePvControlRecentPhysicalEvents'))
    ? global.get('homePvControlRecentPhysicalEvents')
    : [];
// Keep newly finalized events for the normal 30-second association window. Once a
// known cause has actually been consumed for headline attribution, retain it beyond
// 30 seconds only while it has been revalidated at the normal cadence and never past
// the 60-second sustained-cause ceiling. This pre-filter intentionally mirrors the
// consumer lifetime rule so sustained events are not discarded before revalidation.
const physicalEventRepeatGapMs = Math.max(3000, Math.min(60000, NOMINAL_EVALUATION_MS * 1.75));
physicalEvents = physicalEvents
    .filter(event => {
        if (!event || !Number.isFinite(Number(event.ts))) return false;
        const age = now - Number(event.ts);
        const recentlyRevalidated = Number.isFinite(Number(event.lastHeadlineMatchTs)) &&
            now - Number(event.lastHeadlineMatchTs) <= physicalEventRepeatGapMs;
        return age <= PHYSICAL_EVENT_MEMORY_MS ||
            (Number(event.headlineUseCount || 0) > 0 && recentlyRevalidated && age <= PHYSICAL_EVENT_SUSTAIN_MAX_MS);
    })
    .slice(-PHYSICAL_EVENT_MAX_EVENTS);
let pendingPhysicalEvent = global.get('homePvControlPendingPhysicalEvent') || null;
if (pendingPhysicalEvent && (
    !Number.isFinite(Number(pendingPhysicalEvent.triggerTs)) ||
    now - Number(pendingPhysicalEvent.triggerTs) > PHYSICAL_EVENT_PENDING_MAX_AGE_MS ||
    Number(pendingPhysicalEvent.continuityGeneration || 0) !== Number(detectorContinuityGeneration)
)) {
    pendingPhysicalEvent = null;
    global.set('homePvControlPendingPhysicalEvent', null);
}
let lastExternalLimitChange = global.get('homePvControlLastExternalLimitChange') || null;
if (lastExternalLimitChange && (!Number.isFinite(Number(lastExternalLimitChange.ts)) || now - Number(lastExternalLimitChange.ts) > COMMAND_LAG_ATTRIBUTION_MS)) {
    lastExternalLimitChange = null;
    global.set('homePvControlLastExternalLimitChange', null);
}

function detectorSnapshot() {
    return {
        ts: now,
        grid: Number(grid),
        pv: Number(pvPower),
        batteryReliable: physicalBatteryReliable === true,
        batteryPower: physicalBatteryReliable ? Number(detectorBatteryPower) : null,
        houseLoad: physicalBatteryReliable ? Number(detectorHouseLoad) : null,
        limit: Number(currentLimitTotalForAccuracy),
        signalTs: {
            grid: stateTimestampMs(gridEntity),
            pv: stateTimestampMs(pvPowerEntity),
            battery: latestBatteryTimestampMs(),
            limit: latestLimitTimestampMs()
        },
        freshTs: {
            grid: stateFreshnessTimestampMs(gridEntity),
            pv: stateFreshnessTimestampMs(pvPowerEntity),
            battery: earliestBatteryFreshnessTimestampMs(),
            limit: latestLimitTimestampMs()
        },
        batteryReliabilityModes: physicalBatteryRows.map(row => ({
            index: Number(row.index), mode: String(row.reliabilityMode || 'unreliable'),
            fullBoundaryIdleFallback: row.fullBoundaryIdleFallback === true
        }))
    };
}

function finalizePendingPhysicalEvent(pending, current) {
    if (!pending || !pending.baseline || !current) return null;
    const baseline = pending.baseline;
    // Keep the original grid step fixed as the physical event being explained. The
    // later reconciliation sample is used only to obtain fresher PV/battery/limit
    // evidence. This preserves short appliance pulses that recover before the delayed
    // companion sensors have reported, while still allowing a delayed cloud/PV change
    // to explain the original grid spike.
    const gridDelta = Number(pending.triggerGridDelta || 0);
    const trigger = pending.trigger || {};
    const rawPvDelta = Number(current.pv) - Number(baseline.pv || 0);
    const limitDelta = Number(current.limit) - Number(baseline.limit || 0);

    // Battery causality is frozen at the grid trigger. A battery can react to the
    // grid excursion after it happens (for example, a Marstek backing discharge down
    // toward 0 W after a large import step). That later reaction must not be allowed
    // to retroactively explain the original grid spike as Other. Use only the battery
    // movement already visible at trigger time for the triggering event; any movement
    // between trigger and reconciliation belongs to the later detector interval.
    const noConfiguredPhysicalBatteries = configuredPhysicalBatteryCount === 0;
    const batteryTriggerPairReliable = noConfiguredPhysicalBatteries || (
        baseline.batteryReliable === true && trigger.batteryReliable === true &&
        Number.isFinite(Number(baseline.batteryPower)) && Number.isFinite(Number(trigger.batteryPower))
    );
    const triggerBatteryDelta = noConfiguredPhysicalBatteries
        ? 0
        : (batteryTriggerPairReliable
            ? Number(trigger.batteryPower) - Number(baseline.batteryPower)
            : 0);
    const triggerBatteryGridEffect = -triggerBatteryDelta;

    const postTriggerBatteryPairReliable = noConfiguredPhysicalBatteries || (
        trigger.batteryReliable === true && current.batteryReliable === true &&
        Number.isFinite(Number(trigger.batteryPower)) && Number.isFinite(Number(current.batteryPower))
    );
    const postTriggerBatteryDelta = noConfiguredPhysicalBatteries
        ? 0
        : (postTriggerBatteryPairReliable
            ? Number(current.batteryPower) - Number(trigger.batteryPower)
            : 0);

    const pvFreshAfterTrigger = Number.isFinite(Number(current.freshTs?.pv)) &&
        Number(current.freshTs.pv) >= Number(pending.triggerTs);
    const batteryFreshAfterTrigger = noConfiguredPhysicalBatteries || (
        Number.isFinite(Number(current.freshTs?.battery)) &&
        Number(current.freshTs.battery) >= Number(pending.triggerTs)
    );
    // PV is deliberately reconciled with a post-trigger sample because OpenDTU may
    // report an irradiance/cloud change after the P1 grid meter. Battery is different:
    // it is a closed-loop actuator that can react to the grid spike itself, so House
    // load inference requires a reliable trigger-time battery snapshot, not a later
    // battery response.
    const houseLoadPairReliable = batteryTriggerPairReliable && pvFreshAfterTrigger;
    const houseInferenceBlockReason = houseLoadPairReliable
        ? ''
        : !batteryTriggerPairReliable
            ? 'House inference blocked: battery trigger snapshot unreliable'
            : !pvFreshAfterTrigger
                ? 'House inference blocked: PV observation not fresh after trigger'
                : 'House inference blocked: physical evidence incomplete';

    const lastCommand = pending.commandAtTrigger || global.get('homePvControlLastPvCommand') || {};
    const commandTs = Number(lastCommand.ts);
    const commandAge = Number.isFinite(commandTs) ? Math.max(0, now - commandTs) : Infinity;
    // A command may explain the triggering event only if it existed before the grid
    // trigger. A write issued in response to an oven/load spike must never be retroactively
    // blamed for the spike itself.
    const commandPredatesTrigger = Number.isFinite(commandTs) && commandTs < Number(pending.triggerTs);
    const pvSignalTs = Number(current.signalTs?.pv);
    const commandPrecedesObservedPv = commandPredatesTrigger &&
        commandTs < (Number.isFinite(pvSignalTs) ? pvSignalTs : now);
    const observedCommandedLimitDelta = commandPredatesTrigger
        ? commandPathObservedDelta(lastCommand, Number(baseline.limit || 0), Number(current.limit || 0))
        : 0;

    // A *new* HPVC command can be issued after the grid trigger but before the delayed
    // reconciliation sample arrives. Its plant response belongs to the following control
    // interval; it must not be allowed to explain the older trigger as PV availability or
    // inflate the residual House-load estimate. Strip only the bounded PV movement that
    // is physically consistent with the post-trigger HPVC limit path. Any remaining delayed
    // PV movement stays available to explain a genuine cloud/irradiance event.
    const triggerLimit = Number.isFinite(Number(trigger.limit)) ? Number(trigger.limit) : Number(baseline.limit || 0);
    const triggerPv = Number.isFinite(Number(trigger.pv))
        ? Number(trigger.pv)
        : (Number.isFinite(Number(baseline.pv)) ? Number(baseline.pv) : 0);
    const postTriggerObservedPvDelta = Number(current.pv) - triggerPv;

    // Reconcile every HPVC command issued after the original grid trigger, not just
    // the latest one. For each command, use the next command's observed before-limit
    // (or the current limit for the last command) as the end of that command's
    // physically observed path. Then consume only PV movement with the same direction,
    // bounded by that observed path. This keeps rapid command A -> command B sequences
    // from leaking commanded PV response into PV availability or House-load residuals.
    let commandHistory = Array.isArray(global.get('homePvControlPvCommandHistory'))
        ? global.get('homePvControlPvCommandHistory').filter(item => item && Number.isFinite(Number(item.ts)))
        : [];
    const latestCommand = global.get('homePvControlLastPvCommand') || {};
    if (Number.isFinite(Number(latestCommand.ts)) && !commandHistory.some(item => Number(item.ts) === Number(latestCommand.ts))) {
        commandHistory.push(latestCommand);
    }
    const postTriggerCommands = commandHistory
        .filter(item => {
            const ts = Number(item.ts);
            const verification = String(item.verification || 'pending');
            return Number.isFinite(ts) &&
                ts >= Number(pending.triggerTs) && ts <= now && ts !== commandTs &&
                !['failed','superseded'].includes(verification);
        })
        .sort((a, b) => Number(a.ts) - Number(b.ts));

    let postTriggerCommandedLimitDelta = 0;
    let postTriggerControllerPvComponent = 0;
    let remainingPostTriggerPvDelta = postTriggerObservedPvDelta;
    for (let i = 0; i < postTriggerCommands.length; i++) {
        const command = postTriggerCommands[i];
        const commandBefore = Number.isFinite(Number(command.beforeLimit))
            ? Number(command.beforeLimit)
            : (i === 0 ? triggerLimit : Number(postTriggerCommands[i - 1].targetLimit));
        const observedEndLimit = i + 1 < postTriggerCommands.length && Number.isFinite(Number(postTriggerCommands[i + 1].beforeLimit))
            ? Number(postTriggerCommands[i + 1].beforeLimit)
            : Number(current.limit || 0);
        const observedDelta = commandPathObservedDelta(command, commandBefore, observedEndLimit);
        if (Math.abs(observedDelta) < PHYSICAL_COMPONENT_NOISE_W) continue;
        postTriggerCommandedLimitDelta += observedDelta;
        if (Math.abs(remainingPostTriggerPvDelta) >= PHYSICAL_COMPONENT_NOISE_W &&
            Math.sign(observedDelta) === Math.sign(remainingPostTriggerPvDelta)) {
            const claimAbs = Math.min(Math.abs(observedDelta), Math.abs(remainingPostTriggerPvDelta));
            const claim = Math.sign(remainingPostTriggerPvDelta) * claimAbs;
            postTriggerControllerPvComponent += claim;
            remainingPostTriggerPvDelta -= claim;
        }
    }
    const pvDelta = rawPvDelta - postTriggerControllerPvComponent;
    const uncommandedObservedLimitDelta = limitDelta - observedCommandedLimitDelta - postTriggerCommandedLimitDelta;

    if (Math.abs(observedCommandedLimitDelta) >= PHYSICAL_COMPONENT_NOISE_W) {
        addPvResponseAuthority(lastCommand, observedCommandedLimitDelta);
    }
    if (Math.abs(uncommandedObservedLimitDelta) >= PHYSICAL_COMPONENT_NOISE_W) {
        global.set('homePvControlPvResponseAuthority', null);
        lastExternalLimitChange = { ts: now, delta: uncommandedObservedLimitDelta };
        global.set('homePvControlLastExternalLimitChange', lastExternalLimitChange);
        addExternalPvResponseAuthority(uncommandedObservedLimitDelta, 'detector');
    }

    let controllerPvComponent = 0;
    if (Math.abs(observedCommandedLimitDelta) >= PHYSICAL_COMPONENT_NOISE_W &&
        Math.abs(pvDelta) >= PHYSICAL_COMPONENT_NOISE_W &&
        Math.sign(observedCommandedLimitDelta) === Math.sign(pvDelta)) {
        const claimAbs = Math.min(Math.abs(observedCommandedLimitDelta), Math.abs(pvDelta));
        controllerPvComponent = Math.sign(pvDelta) * claimAbs;
        const authority = getPvResponseAuthority();
        if (authority && Number(authority.commandTs) === commandTs) {
            authority.remainingAbs = Math.max(0, Number(authority.remainingAbs || 0) - claimAbs);
            global.set('homePvControlPvResponseAuthority', authority.remainingAbs >= PHYSICAL_COMPONENT_NOISE_W ? authority : null);
        }
    } else if (Math.abs(limitDelta) < PHYSICAL_COMPONENT_NOISE_W && commandPrecedesObservedPv) {
        controllerPvComponent = claimPvResponseAuthority(pvDelta, true);
    }

    const pvAfterControl = pvDelta - controllerPvComponent;
    const externalLimitPvComponent = claimExternalPvResponseAuthority(pvAfterControl, 'detector');
    const pvAvailabilityComponent = pvAfterControl - externalLimitPvComponent;
    const batterySignalTs = Number(trigger.signalTs?.battery);
    const chargePriorityCommandBeforeTriggerBatterySample =
        commandPredatesTrigger &&
        commandTs < (Number.isFinite(batterySignalTs) ? batterySignalTs : Number(pending.triggerTs)) &&
        (commandCurrentlyApplied(lastCommand) || Math.abs(observedCommandedLimitDelta) >= PHYSICAL_COMPONENT_NOISE_W) &&
        commandAge <= COMMAND_LAG_ATTRIBUTION_MS &&
        String(lastCommand.action || '') === 'charge_priority_increase';
    const batteryHpvcCausal =
        !noConfiguredPhysicalBatteries &&
        batteryTriggerPairReliable &&
        Math.abs(triggerBatteryDelta) >= PHYSICAL_COMPONENT_NOISE_W &&
        chargePriorityCommandBeforeTriggerBatterySample;
    const independentBatteryClassifiedOther =
        !noConfiguredPhysicalBatteries && batteryTriggerPairReliable &&
        Math.abs(triggerBatteryDelta) >= PHYSICAL_COMPONENT_NOISE_W && !batteryHpvcCausal;
    const fullBoundaryBatteryEvidenceUsed = Array.isArray(trigger.batteryReliabilityModes) &&
        trigger.batteryReliabilityModes.some(row => row && row.fullBoundaryIdleFallback === true);
    const classificationNotes = [];
    if (houseLoadPairReliable) classificationNotes.push('House inference available: coherent trigger battery and fresh post-trigger PV');
    else classificationNotes.push(houseInferenceBlockReason);
    if (Math.abs(postTriggerControllerPvComponent) >= PHYSICAL_COMPONENT_NOISE_W) {
        classificationNotes.push(`PV candidate adjusted: ${Math.round(Math.abs(postTriggerControllerPvComponent))} W post-trigger HPVC response stripped`);
    }
    if (independentBatteryClassifiedOther) classificationNotes.push('Battery movement classified: independent → Other');
    if (batteryHpvcCausal) classificationNotes.push('Battery movement classified: HPVC Charge Priority → Control');
    if (fullBoundaryBatteryEvidenceUsed) classificationNotes.push('Battery cutoff evidence: full-boundary idle 0 W accepted as reliable');

    // Reconcile the *original trigger grid step*. Delayed PV telemetry may explain
    // that trigger because the PV sensor can report the same physical cloud event late.
    // Battery attribution is intentionally trigger-bounded: only battery movement that
    // was already present at the trigger may explain the original event. A later battery
    // reaction is recorded diagnostically and is left for the next detector interval.
    const effects = {
        load: 0,
        control: -controllerPvComponent + (batteryHpvcCausal ? triggerBatteryGridEffect : 0),
        pv: -pvAvailabilityComponent,
        other: (batteryHpvcCausal ? 0 : triggerBatteryGridEffect) - externalLimitPvComponent
    };
    const knownSigned = ['control','pv','other']
        .reduce((sum, key) => sum + Number(effects[key] || 0), 0);
    const reconciledResidual = gridDelta - knownSigned;
    if (Number.isFinite(reconciledResidual)) {
        if (houseLoadPairReliable) effects.load = reconciledResidual;
        else effects.other += reconciledResidual;
    }
    const explainedSigned = ['control','load','pv','other']
        .reduce((sum, key) => sum + Number(effects[key] || 0), 0);
    const unexplainedGridResidual = gridDelta - explainedSigned;
    if (Number.isFinite(unexplainedGridResidual) && Math.abs(unexplainedGridResidual) > 1e-9) {
        effects.other += unexplainedGridResidual;
    }
    const houseLoadDelta = houseLoadPairReliable ? Number(effects.load || 0) : 0;
    if (Math.abs(controllerPvComponent) >= PHYSICAL_COMPONENT_NOISE_W) {
        classificationNotes.push(`PV movement classified: ${Math.round(Math.abs(controllerPvComponent))} W pre-trigger HPVC response → Control`);
    }
    if (Math.abs(externalLimitPvComponent) >= PHYSICAL_COMPONENT_NOISE_W) {
        classificationNotes.push(`PV movement classified: ${Math.round(Math.abs(externalLimitPvComponent))} W external/manual inverter-limit response → Other`);
    }
    if (Math.abs(pvAvailabilityComponent) >= PHYSICAL_COMPONENT_NOISE_W) {
        classificationNotes.push(`PV movement classified: ${Math.round(Math.abs(pvAvailabilityComponent))} W uncommanded PV change → PV availability`);
    }
    if (houseLoadPairReliable && Math.abs(houseLoadDelta) >= PHYSICAL_COMPONENT_NOISE_W) {
        classificationNotes.push(`House load inferred: ${Math.round(houseLoadDelta)} W physical residual`);
    } else if (!houseLoadPairReliable && Math.abs(reconciledResidual) >= PHYSICAL_COMPONENT_NOISE_W) {
        classificationNotes.push(`Unexplained grid residual routed → Other because House inference is unavailable`);
    }

    const eventExcursionSide = Number(pending.excursionSide || 0);
    if (eventExcursionSide === 0) return null;
    const eventId = `${Number(pending.triggerTs)}:${Math.round(Number(pending.triggerGridDelta || 0))}:${physicalEvents.length}`;
    const event = {
        id: eventId,
        ts: Number(pending.triggerTs),
        finalizedTs: now,
        dtMs: Math.max(0, now - Number(baseline.ts || pending.triggerTs)),
        gridDelta,
        triggerGridDelta: Number(pending.triggerGridDelta || 0),
        gridBefore: Number(baseline.grid || 0),
        gridAfter: Number(pending.trigger?.grid ?? (Number(baseline.grid || 0) + gridDelta)),
        excursionSide: eventExcursionSide,
        effects,
        values: {
            pvDelta,
            rawPvDelta,
            postTriggerObservedPvDelta,
            postTriggerCommandedLimitDelta,
            postTriggerControllerPvComponent,
            postTriggerCommandTs: postTriggerCommands.length > 0 ? Number(postTriggerCommands[postTriggerCommands.length - 1].ts) : null,
            postTriggerCommandCount: postTriggerCommands.length,
            postTriggerCommandTimestamps: postTriggerCommands.map(item => Number(item.ts)),
            batteryDelta: batteryTriggerPairReliable ? triggerBatteryDelta : null,
            triggerBatteryDelta: batteryTriggerPairReliable ? triggerBatteryDelta : null,
            postTriggerBatteryDelta: postTriggerBatteryPairReliable ? postTriggerBatteryDelta : null,
            houseLoadDelta: houseLoadPairReliable ? houseLoadDelta : null,
            batteryReliable: batteryTriggerPairReliable,
            pvFreshAfterTrigger,
            batteryFreshAfterTrigger,
            houseLoadCoherent: houseLoadPairReliable,
            houseInferenceBlockReason,
            fullBoundaryBatteryEvidenceUsed,
            independentBatteryClassifiedOther,
            classificationNotes: classificationNotes.slice(),
            limitDelta,
            observedCommandedLimitDelta,
            uncommandedObservedLimitDelta,
            controllerPvComponent,
            externalLimitPvComponent,
            pvAvailabilityComponent,
            unexplainedGridResidual
        },
        signalTs: current.signalTs,
        commandTs: commandPredatesTrigger ? commandTs : null,
        commandAction: commandPredatesTrigger ? String(lastCommand.action || '') : '',
        commandVerification: commandPredatesTrigger ? String(lastCommand.verification || '') : '',
        continuityGeneration: detectorContinuityGeneration,
        usedForHeadline: false,
        usedAt: null,
        headlineUseCount: 0,
        lastHeadlineMatchTs: null,
        sustainedUntilTs: Number(pending.triggerTs) + PHYSICAL_EVENT_SUSTAIN_MAX_MS,
        physicalAfter: {
            grid: Number(current.grid || 0),
            pv: Number(current.pv || 0),
            batteryReliable: current.batteryReliable === true,
            batteryPower: Number.isFinite(Number(current.batteryPower)) ? Number(current.batteryPower) : null,
            houseLoad: Number.isFinite(Number(current.houseLoad)) ? Number(current.houseLoad) : null,
            limit: Number(current.limit || 0)
        }
    };

    // The grid may already have recovered while this trigger was waiting for sensor
    // reconciliation. Resolve the finalized event immediately in that case so it can
    // never be attached to a later unrelated excursion on the same action-band side.
    const recoveredBeforeFinalize = eventExcursionSide > 0
        ? Number(current.grid) <= importRecalc
        : Number(current.grid) >= exportStart;
    event.resolved = recoveredBeforeFinalize;
    event.resolvedAt = recoveredBeforeFinalize ? now : null;

    const previewWeights = normalizePhysicalWeights(effects, eventExcursionSide);
    const deferredHeadlineBurden = Math.max(0, Number(pending.headlineBurden || 0));
    if (deferredHeadlineBurden > 0 && previewWeights) {
        // Triggering headline samples are temporarily placed in Other while sensor
        // updates reconcile. Move that exact burden to the finalized physical weights.
        dailyAccuracy.headlineFactorSqZDt.other = Math.max(0,
            Number(dailyAccuracy.headlineFactorSqZDt.other || 0) - deferredHeadlineBurden);
        for (const key of ['control','load','pv','other']) {
            const share = Number(previewWeights[key] || 0);
            if (share <= 0) continue;
            dailyAccuracy.headlineFactorSqZDt[key] =
                Number(dailyAccuracy.headlineFactorSqZDt[key] || 0) + deferredHeadlineBurden * share;
        }
        event.usedForHeadline = false;
        event.usedAt = now;
        event.headlineUseCount = Number(event.headlineUseCount || 0) + 1;
        event.lastHeadlineMatchTs = now;
    }

    physicalEvents.push(event);
    physicalEvents = physicalEvents.slice(-PHYSICAL_EVENT_MAX_EVENTS);
    pushAttributionDiagnostic({
        phase: 'reconciled',
        eventId,
        eventAgeMs: Math.max(0, now - Number(pending.triggerTs)),
        reconcileMs: Math.max(0, now - Number(pending.triggerTs)),
        excursionSide: eventExcursionSide,
        gridDelta,
        triggerGridDelta: Number(pending.triggerGridDelta || 0),
        effects: { ...effects },
        weights: previewWeights,
        pvDelta,
        batteryDelta: batteryTriggerPairReliable ? triggerBatteryDelta : null,
        triggerBatteryDelta: batteryTriggerPairReliable ? triggerBatteryDelta : null,
        postTriggerBatteryDelta: postTriggerBatteryPairReliable ? postTriggerBatteryDelta : null,
        houseLoadDelta: houseLoadPairReliable ? houseLoadDelta : null,
        batteryReliable: batteryTriggerPairReliable,
        pvFreshAfterTrigger,
        batteryFreshAfterTrigger,
        houseLoadCoherent: houseLoadPairReliable,
        houseInferenceBlockReason,
        fullBoundaryBatteryEvidenceUsed,
        independentBatteryClassifiedOther,
        classificationNotes: classificationNotes.slice(),
        postTriggerControllerPvComponent,
        limitDelta,
        observedCommandedLimitDelta,
        uncommandedObservedLimitDelta,
        controllerPvComponent,
        externalLimitPvComponent,
        pvAvailabilityComponent,
        unexplainedGridResidual,
        deferredHeadlineBurden,
        commandTs: commandPredatesTrigger ? commandTs : null,
        commandAction: commandPredatesTrigger ? String(lastCommand.action || '') : '',
        commandVerification: commandPredatesTrigger ? String(lastCommand.verification || '') : ''
    });
    return event;
}

// Night Restore is outside the active PV-control attribution domain. Reset the
// detector across that boundary instead of creating expected stale-PV/battery blockers
// that would pollute daytime diagnostics or bridge night into the next morning.
if (detectorCoreInputsValid && !persistentNightRestore) {
    const detectorCurrent = detectorSnapshot();
    // A remembered event is usable only while the grid remains on the same action-band
    // side created by that event. Once grid returns inside the action band, the physical
    // event has been resolved and must not be attached to a later unrelated excursion.
    for (const event of physicalEvents) {
        if (!event || event.resolved === true) continue;
        const side = Number(event.excursionSide || 0);
        if (side > 0 && detectorCurrent.grid <= importRecalc) {
            event.resolved = true; event.resolvedAt = now;
        } else if (side < 0 && detectorCurrent.grid >= exportStart) {
            event.resolved = true; event.resolvedAt = now;
        }
    }

    // Finalize a pending trigger as soon as one normal evaluation has elapsed AND
    // PV has produced a genuinely fresh post-trigger observation. If OpenDTU is late,
    // keep the event open up to the adaptive 20-30 s deadline. This preserves event
    // throughput on healthy telemetry while still preventing false Other attribution.
    const pendingAgeMs = pendingPhysicalEvent && Number.isFinite(Number(pendingPhysicalEvent.triggerTs))
        ? Math.max(0, now - Number(pendingPhysicalEvent.triggerTs)) : 0;
    const pendingPvEvidenceReady = pendingPhysicalEvent &&
        pendingAgeMs >= Math.max(5000, Math.min(15000, NOMINAL_EVALUATION_MS)) &&
        Number.isFinite(Number(detectorCurrent.freshTs?.pv)) &&
        Number(detectorCurrent.freshTs.pv) >= Number(pendingPhysicalEvent.triggerTs);
    if (pendingPhysicalEvent && (pendingPvEvidenceReady || now >= Number(pendingPhysicalEvent.finalizeAt || 0))) {
        finalizePendingPhysicalEvent(pendingPhysicalEvent, detectorCurrent);
