        global.set('homePvControlPendingPhysicalEvent', null);
    }

    const detectorPrevious = global.get('homePvControlPhysicalDetectorSample');
    if (detectorPrevious && Number.isFinite(Number(detectorPrevious.ts))) {
        const detectorDt = now - Number(detectorPrevious.ts);
        if (detectorDt > 0 && detectorDt <= PHYSICAL_EVENT_MAX_GAP_MS) {
            const detectorThreshold = Math.max(Number(deadband || 0), 25);
            const gridDelta = detectorCurrent.grid - Number(detectorPrevious.grid || 0);
            if (Math.abs(gridDelta) >= detectorThreshold && !pendingPhysicalEvent) {
