global.set('homePvControlPhysicalDetectorGeneration', detectorContinuityGeneration);
global.set('homePvControlRecentPhysicalEvents', physicalEvents);
global.set('homePvControlPendingPhysicalEvent', pendingPhysicalEvent);

function consumeRecentPhysicalEventWeights(harmfulDirection) {
    if (!Number.isFinite(Number(harmfulDirection)) || Number(harmfulDirection) === 0) return null;
    let events = Array.isArray(global.get('homePvControlRecentPhysicalEvents'))
        ? global.get('homePvControlRecentPhysicalEvents')
        : [];
    const nominalRepeatGap = Math.max(3000, Math.min(60000, NOMINAL_EVALUATION_MS * 1.75));
    events = events
        .filter(event => {
            if (!event || !Number.isFinite(Number(event.ts))) return false;
            const age = now - Number(event.ts);
            const recentlyRevalidated = Number.isFinite(Number(event.lastHeadlineMatchTs)) &&
                now - Number(event.lastHeadlineMatchTs) <= nominalRepeatGap;
            return age <= PHYSICAL_EVENT_MEMORY_MS ||
                (Number(event.headlineUseCount || 0) > 0 && recentlyRevalidated && age <= PHYSICAL_EVENT_SUSTAIN_MAX_MS);
        })
        .slice(-PHYSICAL_EVENT_MAX_EVENTS);

    const latestPhysical = global.get('homePvControlPhysicalDetectorSample') || null;
    function sustainedWeightsStillConsistent(event, weights) {
