        // known cause is revalidated independently, stale causes are masked out, and
        // the remaining active causes are renormalized. Pure Other stays one-shot.
        if (Number(event.headlineUseCount || 0) <= 0) return { ...weights };
        if (!latestPhysical || !event.physicalAfter) return null;

        const after = event.physicalAfter || {};
        const values = event.values || {};
        const active = { control: false, load: false, pv: false };

        if (Number(weights.load || 0) > 0.05 && Number.isFinite(Number(after.houseLoad)) &&
            latestPhysical.batteryReliable === true && Number.isFinite(Number(latestPhysical.houseLoad))) {
            const delta = Math.abs(Number(values.houseLoadDelta || 0));
            const tolerance = Math.max(100, deadband * 2, delta * 0.35);
            active.load = Math.abs(Number(latestPhysical.houseLoad) - Number(after.houseLoad)) <= tolerance;
        }
        if (Number(weights.pv || 0) > 0.05 && Number.isFinite(Number(after.pv)) && Number.isFinite(Number(latestPhysical.pv))) {
            const delta = Math.abs(Number(values.pvAvailabilityComponent || values.pvDelta || 0));
            const tolerance = Math.max(100, deadband * 2, delta * 0.40);
            active.pv = Math.abs(Number(latestPhysical.pv) - Number(after.pv)) <= tolerance;
        }
        if (Number(weights.control || 0) > 0.05 && Number.isFinite(Number(after.limit)) && Number.isFinite(Number(latestPhysical.limit))) {
            const delta = Math.abs(Number(values.observedCommandedLimitDelta || values.limitDelta || 0));
            const tolerance = Math.max(50, deadband, delta * 0.25);
            const latestCommand = global.get('homePvControlLastPvCommand') || {};
            const eventCommandTs = Number(event.commandTs);
            const latestCommandTs = Number(latestCommand.ts);
            const sameOriginatingCommand = Number.isFinite(eventCommandTs) && Number.isFinite(latestCommandTs) &&
                latestCommandTs === eventCommandTs;
            const originatingCommandStillApplied = sameOriginatingCommand && commandCurrentlyApplied(latestCommand);
