        for (const key of ['control','load','pv']) masked[key] /= activeTotal;
        return masked;
    }

    // Match the newest still-active event that created the same action-band excursion.
    // A sustained cause may contribute to several time-weighted headline samples, but
    // only while the physical state remains consistent and continuously revalidated.
    for (let index = events.length - 1; index >= 0; index--) {
        const event = events[index];
        if (event.resolved === true) continue;
        if (Number(event.continuityGeneration || 0) !== Number(detectorContinuityGeneration)) continue;
        if (Number(event.excursionSide || 0) !== Number(harmfulDirection)) continue;
        if (Number(harmfulDirection) * Number(event.gridDelta || 0) <= 0) continue;
        const gridBefore = Number(event.gridBefore);
        const gridAfter = Number(event.gridAfter);
        if (!Number.isFinite(gridBefore) || !Number.isFinite(gridAfter)) continue;
        const eventAfterExcursion = Math.max(0, Number(harmfulDirection) * (gridAfter - exportTarget));
        const currentExcursion = Math.max(0, Number(harmfulDirection) * (grid - exportTarget));
        const retainedFraction = eventAfterExcursion > 0 ? currentExcursion / eventAfterExcursion : 0;
        if (retainedFraction < 0.25) continue;
