        if (!baseWeights) continue;
        const weights = sustainedWeightsStillConsistent(event, baseWeights);
        if (!weights) continue;

        event.usedForHeadline = false; // retained only for backward-compatible diagnostics
        event.usedAt = now;
        event.headlineUseCount = Number(event.headlineUseCount || 0) + 1;
        event.lastHeadlineMatchTs = now;
        global.set('homePvControlRecentPhysicalEvents', events);
        pushAttributionDiagnostic({
            phase: Number(event.headlineUseCount || 0) > 1 ? 'headline-sustained' : 'headline-consumed',
            eventId: String(event.id || ''),
            eventAgeMs: Math.max(0, now - Number(event.ts || now)),
            headlineUseCount: Number(event.headlineUseCount || 0),
            excursionSide: Number(event.excursionSide || 0),
            gridDelta: Number(event.gridDelta || 0),
            retainedFraction,
            effects: { ...(event.effects || {}) },
            baseWeights: { ...baseWeights },
            weights: { ...weights },
            values: { ...(event.values || {}) },
            commandTs: Number.isFinite(Number(event.commandTs)) ? Number(event.commandTs) : null,
            commandAction: String(event.commandAction || ''),
            commandVerification: String(event.commandVerification || '')
        });
        return weights;
    }
    global.set('homePvControlRecentPhysicalEvents', events);
    return null;
}

const accuracyBindingMargin = Math.max(deadband, 50);
// Score only when configured inverter limits appear physically binding. A limit
// below maximum does not curtail PV when available solar is below that limit.
const limitAppearsBindingForAccuracy =
    currentLimitTotalForAccuracy > 0 &&
    pvPower >= (currentLimitTotalForAccuracy - accuracyBindingMargin);
// A PV correction can start cooldown in the very same evaluation that observed the
// grid/load excursion which triggered that correction. Excluding that evaluation would
// throw away the pre-response measurement (for example an oven switching on) and make
// House load attribution impossible. Allow only the evaluation that *starts* cooldown;
// later cooldown evaluations remain excluded while the inverter/plant is settling.
const lastPvWriteMsForAccuracy = Number(flow.get('homePvControlLastPvWriteMs') || 0);
const cooldownStartedThisEvaluation =
    cooldownActiveNow === true &&
    lastPvWriteMsForAccuracy > 0 &&
    lastPvWriteMsForAccuracy === now;
const cooldownEligibleForAccuracy = !cooldownActiveNow || cooldownStartedThisEvaluation;

const targetAccuracyEligible =
    enabled &&
    stateIsNumeric(gridEntity) &&
    stateIsNumeric(pvPowerEntity) &&
    thresholdConfigurationValid &&
    pvLimitedForAccuracy &&
    limitAppearsBindingForAccuracy &&
    !wantsMinimumPv &&
    !persistentNightRestore &&
    // Charge Priority is excluded only while it is actually influencing PV control.
    hbcResponseWindowActive !== true &&
    hbcExportLimitingSuppressed !== true &&
    pvAction !== 'charge_priority_increase' &&
    cooldownEligibleForAccuracy &&
    !['Disabled', 'Waiting for inputs', 'Waiting for restore', 'Inputs unavailable', 'Configuration error'].includes(status);

if (!targetAccuracyEligible) {
    dailyAccuracy.lastEligibleSampleTs = null;
    dailyAccuracy.previousTargetSample = null;
} else {
    const previousEligibleTs = Number(dailyAccuracy.lastEligibleSampleTs);
    const gapOpener = !Number.isFinite(previousEligibleTs) || previousEligibleTs <= 0;
    const rawDt = gapOpener ? NOMINAL_EVALUATION_MS : Math.max(0, now - previousEligibleTs);
    const dt = gapOpener
        ? NOMINAL_EVALUATION_MS
        : (rawDt > 0 ? Math.min(rawDt, MAX_WEIGHT_MS) : NOMINAL_EVALUATION_MS);

    // Friendly 0-100 headline: side-aware, action-band-referenced NRMSE. Samples
    // inside Export Start...Import Restore have z=0 by policy. Beyond either trigger,
    // normalize the excursion by four times that side's target-to-trigger distance.
    let z = 0;
    if (grid < exportStart) {
        const sideScale = Math.max(Math.abs(exportTarget - exportStart), 1);
        z = (exportStart - grid) / (SCORE_SCALE_K * sideScale);
    } else if (grid > importRecalc) {
        const sideScale = Math.max(Math.abs(importRecalc - exportTarget), 1);
        z = (grid - importRecalc) / (SCORE_SCALE_K * sideScale);
    }

    // Physical engineering metrics are independent of Export Start/Import Restore.
    // They measure tracking to Target Export after allowing the configured deadband.
    const targetError = Math.abs(grid - exportTarget);
    const e = Math.max(0, targetError - deadband);
    const headlineHarmfulDirection = grid > importRecalc
        ? 1
        : (grid < exportStart ? -1 : Math.sign(grid - exportTarget));
    const detectorHeadlineWeights = z > 0
        ? consumeRecentPhysicalEventWeights(headlineHarmfulDirection)
        : null;
    const pendingHeadlineEvent = z > 0 ? (global.get('homePvControlPendingPhysicalEvent') || null) : null;
    const headlineAwaitingReconcile = !!(
        pendingHeadlineEvent &&
        Number(pendingHeadlineEvent.continuityGeneration || 0) === Number(detectorContinuityGeneration) &&
        Number(pendingHeadlineEvent.excursionSide || 0) === Number(headlineHarmfulDirection) &&
        Number.isFinite(Number(pendingHeadlineEvent.triggerTs)) &&
        now - Number(pendingHeadlineEvent.triggerTs) >= 0 &&
        now - Number(pendingHeadlineEvent.triggerTs) <= PHYSICAL_EVENT_MEMORY_MS
    );
    const headlineWeightsFromDetector = detectorHeadlineWeights !== null;

    dailyAccuracy.sumDt += dt;
    dailyAccuracy.sumSqZDt += z * z * dt;
    dailyAccuracy.sumSqEDt += e * e * dt;
    dailyAccuracy.sumEDt += e * dt;
    dailyAccuracy.targetCount += 1;
    if (z > 0) dailyAccuracy.bandExcursionCount += 1;
    if (e > 0) {
