    // attribution. Only z>0 samples can reduce Daily Control Accuracy. The causal
    // classifier below supplies a factor when possible; otherwise the actual
    // excursion is honestly retained as Other/unclassified.
    // Current-state controller evidence is safe to inspect even when this sample
    // opens a new eligibility chain. What is unsafe across a gap are *deltas* to a
    // previous PV/load sample. This distinction prevents real controller excursions
    // after a gap/restart from being forced into Other merely because continuity broke.
    const changeThreshold = Math.max(deadband, 25);
    const currentLimit = inverters.reduce((sum, inv) => sum + Number(inv.current || 0), 0);
    const lastPvWriteMs = Number(flow.get('homePvControlLastPvWriteMs') || 0);
    const writeAgeMs = lastPvWriteMs > 0 ? Math.max(0, now - lastPvWriteMs) : Infinity;
    const recentControllerWrite = writeAgeMs <= targetComparisonWindowMs;
    const settlingActive = pvPostWriteSettling === true;
    const atEffectiveMinimum = inverters.length > 0 && inverters.every(
        inv => inv.current <= (inv.minimum_power + deadband)
