        status === 'PV dynamically adjusted' ||
        status === 'PV restored';
    const latestCommandForEvidence = global.get('homePvControlLastPvCommand') || {};
    const latestCommandAgeForEvidence = Number.isFinite(Number(latestCommandForEvidence.ts))
