    // real observed control boundary. This prevents failed writes from becoming Control.
    const currentControllerEvidence =
        appliedRecentControllerCommand ||
        (settlingActive && appliedRecentControllerCommand) ||
        atEffectiveMinimum ||
        atEffectiveMaximum;

    let headlineWeights = headlineAwaitingReconcile
        ? { control: 0, load: 0, pv: 0, other: 1 }
