                    (commandCurrentlyApplied(lastPvCommand) || Math.abs(observedCommandedLimitDelta) >= PHYSICAL_COMPONENT_NOISE_W) &&
                    commandAgeMs <= COMMAND_LAG_ATTRIBUTION_MS &&
