                const externalWindow = elapsed <= EXTERNAL_WINDOW_MS;
                const comparisonWindow = elapsed <= targetComparisonWindowMs || commandAgeMs <= COMMAND_LAG_ATTRIBUTION_MS;

                // Grid import is positive. Therefore a load rise pushes grid positive,
                // while a PV rise pushes grid negative. For a high-import excursion the
                // harmful direction is +1; for an export excursion it is -1. Only causal
