                const harmfulDirection = grid > importRecalc ? 1 : (grid < exportStart ? -1 : Math.sign(grid - exportTarget));
                const loadGridEffect = houseLoadChange;
                const controlGridEffect = -controllerPvComponent + (batteryHpvcCausal ? batteryGridEffect : 0);
