                    : 0;
                let controlEvidence = comparisonWindow && (Math.abs(controllerPvComponent) >= changeThreshold || batteryHpvcCausal)
                    ? projectedEvidence(controlGridEffect)
                    : 0;
                let pvEvidence = externalWindow && Math.abs(pvAvailabilityResidual) >= changeThreshold
                    ? projectedEvidence(pvGridEffect)
                    : 0;
