                if (loadEvidence === 0 && controlEvidence === 0 && pvEvidence === 0 && otherEvidence === 0 && currentControllerEvidence) {
                    controlEvidence = Math.max(changeThreshold, Math.abs(gridChange));
                }

                const evidenceTotal = loadEvidence + controlEvidence + pvEvidence + otherEvidence;
                const weights = { control: 0, load: 0, pv: 0, other: 0 };
                if (evidenceTotal > 0) {
