        ['Price hysteresis', price(settings.priceHysteresis)],
        ['Force charge at negative price', settings.negativePriceHbcCharge ? 'On' : 'Off'],
        ['Export Start', watts(settings.exportStart, 1)],
        ['Target Export', watts(settings.targetExport, 1)],
        ['Import Restore', watts(settings.importRestore, 1)],
