                ['headroom contribution', `headroom contribution=${watts(battery.headroomContribution)}`],
                ['headroom', `headroom=${watts(battery.headroom)}`],
                ['telemetry', `telemetry=${battery.telemetry}`],
                ['freshness mode', `freshness mode=${battery.freshnessMode}`],
                ['heartbeat age', `heartbeat age=${age(battery.heartbeatAgeSeconds)}`],
                ['power age', `power age=${age(battery.powerAgeSeconds)}`],
                ['SOC age', `SOC age=${age(battery.socAgeSeconds)}`],
                ['reason', `reason=${battery.reason}`]
            ]) txtBattery(token, label);
        }
        htm(`<h3>${esc(battery.name)}</h3>`, `battery ${battery.name}`);
        for (const [label, value] of [
            ['Status', battery.status], ['SOC', soc], ['Actual power', watts(battery.power)],
            ['Charging cutoff', finite(battery.chargingCutoff) ? `${battery.chargingCutoff}%` : 'unavailable'],
            ['Discharging cutoff', finite(battery.dischargingCutoff) ? `${battery.dischargingCutoff}%` : 'unavailable'],
            ['Cutoff source', battery.cutoffSource || 'unknown'],
            ['Maximum charge power', watts(battery.maxChargePower)], ['RS485 control', battery.rs485Enabled ? 'enable' : (battery.rs485State || 'unknown')], ['Effective charge ceiling', watts(battery.effectiveChargeCeiling)],
            ['Learned taper ceiling', finite(battery.learnedTaperCeiling) ? watts(battery.learnedTaperCeiling) : '—'],
            ['Taper SOC band', battery.taperBand || '—'],
            ['Stable charging time', finite(battery.taperStableSeconds) ? `${Math.round(battery.taperStableSeconds)} s` : '—'],
            ['Probe eligible', battery.taperProbeEligible ? 'Yes' : 'No'],
            ['Awaiting taper confirmation', battery.taperAwaitingConfirmation ? 'Yes' : 'No'],
            ['Taper contamination count', Math.max(0, Number(battery.taperContaminationCount || 0))],
            ['Contamination block remaining', age(battery.taperContaminationBlockedSeconds)],
            ['Per-battery taper step cap', watts(battery.taperStepCap)],
            ['Confirmed taper headroom', watts(battery.taperConfirmedHeadroom)],
            ['Controlled taper allowance', watts(battery.taperReleaseAllowance)],
            ['Eligible for Charge Priority', battery.priorityEligible ? 'Yes' : 'No'],
            ['SOC mode', battery.socMode],
            ['Headroom contribution', watts(battery.headroomContribution)],
            ['Charging headroom', watts(battery.headroom)], ['Telemetry', battery.telemetry], ['Freshness mode', battery.freshnessMode],
            ['Heartbeat age', age(battery.heartbeatAgeSeconds)], ['Power age', age(battery.powerAgeSeconds)],
            ['SOC age', age(battery.socAgeSeconds)], ['Reason', battery.reason]
        ]) htm(htmlRow(label, value), `battery ${battery.name} ${label}`);
    }

    for (const sensor of report.sensorHealth || []) {
        const health = `${sensor.status} (${age(sensor.ageSeconds)})`;
        txt(`${sensor.label}: ${health} · ${sensor.entity}`, `sensor ${sensor.label}`);
        htm(`<span>${esc(sensor.label)}</span><strong>${esc(health)}</strong><code>${esc(sensor.entity)}</code>`, `sensor ${sensor.label}`);
    }

    txt(`Insight history source: ${report.insightHistorySource || 'latest-20 fallback'}`, 'Insight history source');
    htm(htmlRow('Insight history source', report.insightHistorySource || 'latest-20 fallback'), 'Insight history source');

    // TXT is the lossless raw-event record; HTML may compact consecutive
    // identical Insights. Validate each renderer against the correct shared-model
    // representation so HTML grouping can never create a false parity failure.
    const rawInsights = Array.isArray(report.insights) ? report.insights : [];
    const groupedInsights = Array.isArray(report.groupedInsights) ? report.groupedInsights : rawInsights;
    const insightSummary = report.insightSummary || { total: 0, grouped: 0, critical: 0, warnings: 0, information: 0 };
    txt(`Events: ${insightSummary.total} · Consecutive entries: ${insightSummary.grouped} · Critical: ${insightSummary.critical} · Warnings: ${insightSummary.warnings} · Info: ${insightSummary.information}`, 'Insight severity summary');
    for (const insight of rawInsights) {
        const severity = String(insight.severity || 'info').toUpperCase();
        txt(`${insight.time} | ${severity} | ${insight.flow} | ${insight.node} | ${insight.explanation}`, `raw insight ${insight.time}`);
    }
    for (const insight of groupedInsights) {
        const count = Math.max(1, Number(insight.count || 1));
        const timeLabel = count > 1 ? `${insight.time}–${insight.lastTime}` : insight.time;
