        htm(esc(insight.explanation), `grouped insight ${timeLabel} explanation`);
        if (count > 1) htm(`×${count}`, `grouped insight ${timeLabel} occurrence count`);
    }
}

ordered(visibleHtml, ['<section id="inverters">','<h3>','Inverter Diagnostics'], 'HTML inverter display order');
ordered(text, ['[INVERTERS]','[INVERTER DIAGNOSTICS]'], 'TXT inverter display order');
ordered(visibleHtml, ['Current HBC State','Negative All-In Override','Charge Priority Capacity','Batteries','HBC & Battery Diagnostics'], 'HTML HBC display order');
ordered(text, ['[CURRENT HBC STATE]','[NEGATIVE ALL-IN OVERRIDE]','[CHARGE PRIORITY CAPACITY]','[BATTERIES]','[HBC & BATTERY DIAGNOSTICS]'], 'TXT HBC display order');

msg.hpvcReportParity = {
    ok: errors.length === 0,
    errors,
    version: report && report.version,
    generated: report && report.generated,
    manifestBytes: expectedManifest.length,
    checkedVisibleValues: true
};

// Report publication must not be blocked by a cosmetic HTML/TXT parity mismatch.
// The previous hard-fail could leave the dashboard returning to "Generate report"
// instead of exposing the successfully rendered report. Keep structural/model
// failures fatal, but publish a complete rendered report when only visible-value
// parity checks disagree and record the mismatch for diagnostics.
const criticalParityErrors = errors.filter(error =>
    error === 'shared report model missing' ||
    error === 'parity manifest missing' ||
    error === 'TXT renderer manifest differs from shared model' ||
    error === 'HTML renderer manifest differs from shared model'
);
if (criticalParityErrors.length > 0) {
    throw new Error(`HPVC report structural parity failed: ${criticalParityErrors.join('; ')}`);
}
if (errors.length > 0) {
    node.warn(`HPVC report visible parity warning; publishing report: ${errors.join('; ')}`);
    node.status({ fill: 'yellow', shape: 'ring', text: 'report parity warning' });
}
const parityGenerationId = String(msg.hpvcReportGenerationId || '');
const parityActiveId = String(flow.get('hpvcReportGenerationId') || '');
const parityCancelledId = String(flow.get('hpvcReportCancelledGenerationId') || '');
if (!parityGenerationId || parityGenerationId !== parityActiveId || parityGenerationId === parityCancelledId) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'stale report discarded' });
    return null;
}
msg.payload = html;
return msg;

const generationId = String(msg.hpvcReportGenerationId || '');
const activeId = String(flow.get('hpvcReportGenerationId') || '');
if (!generationId || generationId !== activeId) return null;
flow.set('hpvcReportCancelledGenerationId', generationId);
msg.hpvcReportWatchdog = true;
msg.error = { message: 'Report generation watchdog timeout after 45 seconds' };
node.warn('HPVC report generation exceeded 45 seconds; cancelling this generation and cleaning its temporary file.');
return msg;

const payloadText = String(msg.payload ?? '').trim();

// The report-storage exec emits exactly 'ready' only after the writable mount,
// report directory, and /tmp symlink have all been established successfully.
if (payloadText === 'ready') {
    global.set('homePvControlReportStorageReady', true);
    global.set('homePvControlReportStorageLastAttemptAt', null);
    node.status({ fill: 'green', shape: 'dot', text: 'report storage ready' });

    // Replay one recent Generate Report request that arrived before storage was ready.
    // Limit replay to a recent request so a stale context value cannot unexpectedly
