indow',report.hbc.responseWindowActive?'Active':'Inactive')}${row('HBC response window duration',finite(report.hbc.responseWindowMs)?`${Math.round(report.hbc.responseWindowMs/1000)} s`:'unavailable')}${row('HBC response window remaining',finite(report.hbc.responseWindowRemainingMs)?`${Math.ceil(report.hbc.responseWindowRemainingMs/1000)} s`:'unavailable')}${row('Charge Priority exit hold',report.hbc.exitHoldActive?'Active':'Inactive')}${row('Charge Priority exit hold duration',finite(report.hbc.exitHoldMs)?`${Math.round(report.hbc.exitHoldMs/1000)} s`:'unavailable')}${row('Charge Priority exit hold remaining',finite(report.hbc.exitHoldRemainingMs)?`${Math.ceil(report.hbc.exitHoldRemainingMs/1000)} s`:'unavailable')}${row('Persistent export age',finite(report.hbc.persistentExportAgeMs)?`${Math.round(report.hbc.persistentExportAgeMs/1000)} s`:'unavailable')}${row('Export fallback threshold',finite(report.hbc.exportFallbackMs)?`${Math.round(report.hbc.exportFallbackMs/1000)} s`:'unavailable')}${row('Export fallback',report.hbc.exportFallbackActive?'Active':'Inactive')}${row('HPVC export limiting suppressed',report.hbc.exportLimitingSuppressed?'Yes':'No')}${row('Battery diagnostics timestamp',report.hbc.diagnosticsTime)}${row('Battery diagnostics age',age(report.hbc.diagnosticsAgeSeconds))}</div></section>
